#include <iostream>
#include <thread>
#include <string>
using namespace std;

string bowl1;
string bowl2;

void cleanBowl() {
    bowl1 = "{w1}";
}

void dryFish() {
    bowl2 = "{w2}";
}

int main() {
    thread t1(cleanBowl);
    thread t2(dryFish);
    t1.join();
    t2.join();
    cout << bowl1 << endl;
    cout << bowl2 << endl;
    cout << "两只都回来了喵" << endl;
    return 0;
}
